#include <stdio.h>
int main(void) {
    int values[30] = {0};
    int count = 0;
    if (scanf("%d", &count) != 1 || count < 0 || count > 30) return 1;
    if (count == 0) {
        printf("0\n");
        return 0;
    }
    for (int i = 0; i < count; i++) {
        if (scanf("%d", &values[i]) != 1) return 1;
    }
    int total = 0;
    for (int i = 0; i < count; i++) total += values[i];
    printf("%d\n", total);
    return 0;
}
